private val Rp = NumberFormat.getCurrencyInstance(Locale("id","ID")).apply { maximumFractionDigits=0 }
private fun rp(v:Long?)=Rp.format(v?:0L)
private fun JsonObject.t(vararg k:String)=k.firstNotNullOfOrNull{string(it)?.takeIf(String::isNotBlank)}?:"-"
private fun JsonObject.n(vararg k:String)=k.firstNotNullOfOrNull{long(it)}?:0L
private fun JsonObject.rows()=array("items")?.filterIsInstance<JsonObject>().orEmpty()
private fun initials(s:String)=s.trim().split(" ").filter(String::isNotBlank).take(2).joinToString(""){it.first().uppercase()}.ifBlank{"IC"}

