private data class Cart(val p:JsonObject,val q:Int)
private fun add(c:List<Cart>,p:JsonObject)=c.firstOrNull{it.p.t("id")==p.t("id")}?.let{c.map{z->if(z.p.t("id")==p.t("id"))z.copy(q=z.q+1)else z}}?:c+Cart(p,1)
private fun dec(c:List<Cart>,id:String)=c.mapNotNull{if(it.p.t("id")!=id)it else it.copy(q=it.q-1).takeIf{z->z.q>0}}

