@Composable private fun Metric(a:String,b:String,m:Modifier){Card(m){Column(Modifier.padding(13.dp)){Text(a,style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant);Text(b,style=MaterialTheme.typography.titleLarge);Text("Periode terpilih",style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.primary)}}}
@Composable private fun Chart(rs:List<JsonObject>){Card(Modifier.fillMaxWidth()){Column(Modifier.padding(15.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Grafik Pendapatan",style=MaterialTheme.typography.titleMedium);AssistChip({},label={Text("Per Hari")})};Spacer(Modifier.height(8.dp));if(rs.isEmpty())Text("Data harian belum tersedia dari API.",color=MaterialTheme.colorScheme.onSurfaceVariant)else{val vs=rs.map{it.n("omzet","pendapatan","total","nominal")};Canvas(Modifier.fillMaxWidth().height(170.dp)){val max=(vs.maxOrNull()?:1L).coerceAtLeast(1L).toFloat();val step=if(vs.size<2)size.width else size.width/(vs.size-1);val p=Path();vs.forEachIndexed{i,v->{val x=step*i;val y=size.height-v.toFloat()/max*size.height;if(i==0)p.moveTo(x,y)else p.lineTo(x,y);drawCircle(MaterialTheme.colorScheme.primary,5f,androidx.compose.ui.geometry.Offset(x,y))}};drawPath(p,MaterialTheme.colorScheme.primary,style=Stroke(5f,cap=StrokeCap.Round))}}}}}

@Composable private fun Checkout(r:Repository,done:()->Unit,cancel:()->Unit){var ps by remember{mutableStateOf(emptyList<JsonObject>())};var c by remember{mutableStateOf(emptyList<Cart>())};var method by rememberSaveable{mutableStateOf("tunai")};var customer by rememberSaveable{mutableStateOf("")};var busy by remember{mutableStateOf(false)};var err by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();LaunchedEffect(Unit){runCatching{r.produk()}.onSuccess{ps=it.rows()}.onFailure{err=ApiError.message(it)}};val total=c.sumOf{it.p.n("harga","harga_jual")*it.q};AlertDialog(onDismissRequest=cancel,title={Text("Transaksi Baru")},text={LazyColumn(Modifier.heightIn(max=520.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){if(c.isEmpty())item{Empty("Keranjang kosong","Pilih produk di bawah.")};items(c){x->Card{Row(Modifier.padding(9.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(x.p.t("nama"));Text("${x.q} × ${rp(x.p.n("harga","harga_jual"))}")};IconButton{c=dec(c,x.p.t("id"))}{Icon(Icons.Default.Remove,"Kurangi")};IconButton{c=add(c,x.p)}{Icon(Icons.Default.Add,"Tambah")}}}};items(ps.take(20)){p->Card(onClick={c=add(c,p)}){Row(Modifier.padding(9.dp)){Text(p.t("nama"),Modifier.weight(1f));Text(rp(p.n("harga","harga_jual")))}}};item{OutlinedTextField(customer,{customer=it.filter(Char::isDigit)},label={Text("Pelanggan ID")},modifier=Modifier.fillMaxWidth())};item{Row(horizontalArrangement=Arrangement.spacedBy(5.dp)){listOf("tunai","transfer","bon","cash_tunai").forEach{v->FilterChip(method==v,{method=v},label={Text(v.replace('_',' ').replaceFirstChar{it.uppercase()})})}}};item{Text("Total ${rp(total)}",style=MaterialTheme.typography.titleLarge)};err?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}}}},confirmButton={Button(c.isNotEmpty()&&total>0&&!busy,{if(method=="bon"&&customer.toLongOrNull()==null){err="Pelanggan wajib untuk kasbon.";return@Button};busy=true;scope.launch{runCatching{r.createTransaksi(buildJsonObject{putJsonArray("items"){c.forEach{add(buildJsonObject{put("produk_id",it.p["id"]?:JsonNull);put("qty",it.q)})}};put("metode_bayar",method);customer.toLongOrNull()?.let{put("pelanggan_id",it)}})}.onSuccess{done()}.onFailure{err=ApiError.message(it)};busy=false}}){Text(if(busy)"Memproses…"else"Simpan")}},dismissButton={TextButton(cancel){Text("Batal")}})}